CREATE OR REPLACE FUNCTION public.canonical_tenant_operation_decision(p_company_id uuid, p_operation text)
 RETURNS TABLE(allowed boolean, reason_code text, company_status text, capability_status text, production_status text, state_version bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_company public.companies%rowtype;
  v_capability text;
  v_capability_row public.company_capabilities%rowtype;
  v_production_status text;
  v_base_allowed boolean := false;
  v_evidence jsonb;
  v_api_bundle_active boolean := false;
  v_capability_ready boolean := false;
  v_effective_capability_status text;
begin
  select * into v_company
  from public.companies
  where id = p_company_id;

  if not found then
    return query select false, 'tenant_not_found', null::text, 'missing'::text, null::text, 0::bigint;
    return;
  end if;

  if to_regclass('public.ediel_production_state') is not null then
    execute 'select state from public.ediel_production_state where company_id = $1'
      into v_production_status using p_company_id;
  end if;

  v_production_status := coalesce(
    v_production_status,
    v_company.ediel_production_status,
    v_company.production_status,
    'disabled'
  );

  v_capability := case p_operation
    when 'email.send' then 'email_outbound'
    when 'webhook.deliver' then 'webhooks'
    when 'ediel.production.send' then 'ediel_production'
    when 'ediel.test.process' then 'ediel_test'
    when 'customer_automation.execute' then 'customer_automation'
    when 'facility_lookup.execute' then 'facility_lookup'
    when 'contract_channel.sell' then 'website_sales'
    when 'api_client.execute' then 'api_sales'
    else null
  end;

  if v_capability is not null then
    select * into v_capability_row
    from public.company_capabilities
    where company_id = p_company_id
      and capability_code = v_capability;

    v_capability_ready :=
      coalesce(v_capability_row.enabled, false)
      and coalesce(v_capability_row.readiness_status, 'missing') = 'ready';
  end if;

  if p_operation in (
    'api_client.execute',
    'contract_channel.sell',
    'customer_automation.execute',
    'facility_lookup.execute',
    'email.send',
    'webhook.deliver'
  ) then
    select exists (
      select 1
      from public.integration_api_clients c
      where c.company_id = p_company_id
        and c.status = 'active'
        and c.profile_key = 'tenant_website'
    ) into v_api_bundle_active;
  end if;

  v_effective_capability_status := case
    when v_capability is null then 'not_required'
    when v_capability_ready then coalesce(v_capability_row.readiness_status, 'ready')
    when v_api_bundle_active then 'api_bundle'
    else coalesce(v_capability_row.readiness_status, 'missing')
  end;

  v_base_allowed := case coalesce(v_company.status, '__unknown__')
    when 'onboarding' then p_operation in (
      'tenant.provisioning.execute',
      'ediel.test.process',
      'invitation.accept',
      'company_user.manage',
      'production.prepare',
      'production.pause'
    )
    when 'active' then p_operation in (
      'tenant.provisioning.execute',
      'email.send',
      'webhook.deliver',
      'ediel.production.send',
      'ediel.test.process',
      'customer_automation.execute',
      'facility_lookup.execute',
      'invitation.accept',
      'company_user.manage',
      'production.prepare',
      'production.activate',
      'production.pause',
      'production.resume',
      'contract_channel.sell',
      'api_client.execute'
    )
    else false
  end;

  if not v_base_allowed then
    return query select false,
      case coalesce(v_company.status, '__unknown__')
        when 'paused' then 'tenant_paused'
        when 'suspended' then 'tenant_suspended'
        when 'archived' then 'tenant_archived'
        when 'pending_deletion' then 'tenant_pending_deletion'
        when 'closed' then 'tenant_closed'
        when 'deleted_test_only' then 'tenant_deleted_test_only'
        when 'onboarding' then 'operation_not_allowed_during_onboarding'
        else 'tenant_status_unknown'
      end,
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  if v_capability is not null
     and not v_capability_ready
     and not v_api_bundle_active then
    return query select false,
      'capability_not_ready',
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  -- Customer/contract intake is deliberately decoupled from the Ediel send
  -- lock. A tenant may accept a valid contract while a production transport
  -- change is being revalidated. The downstream Ediel send remains fail-closed
  -- and will not leave the platform until its own gate is live again.
  if p_operation = 'ediel.production.send'
     and v_production_status <> 'live' then
    return query select false,
      'ediel_production_not_live',
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  if p_operation = 'ediel.production.send' then
    v_evidence := public.canonical_ediel_production_evidence_readiness(p_company_id);
    if coalesce((v_evidence->>'ready')::boolean, false) is not true then
      return query select false,
        'ediel_production_evidence_not_ready',
        v_company.status,
        v_effective_capability_status,
        v_production_status,
        v_company.lifecycle_state_version;
      return;
    end if;
  end if;

  return query select true,
    case when v_api_bundle_active and not v_capability_ready then 'allowed_by_tenant_api_bundle' else 'allowed' end,
    v_company.status,
    v_effective_capability_status,
    v_production_status,
    v_company.lifecycle_state_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_partner_contract_v1(p_company_id uuid, p_api_client_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_offer jsonb;
  v_customer jsonb := coalesce(p_payload->'customer', '{}'::jsonb);
  v_site jsonb := coalesce(p_payload->'site', '{}'::jsonb);
  v_agreement jsonb := coalesce(p_payload->'agreement', '{}'::jsonb);
  v_poa jsonb := coalesce(p_payload->'power_of_attorney', '{}'::jsonb);
  v_customer_type text := lower(coalesce(nullif(btrim(v_customer->>'type'), ''), nullif(btrim(v_customer->>'customer_type'), ''), 'private'));
  v_site_type text := lower(coalesce(nullif(btrim(v_site->>'electricity_type'), ''), nullif(btrim(v_site->>'site_electricity_type'), ''), 'consumption'));
  v_offer_reference text := nullif(btrim(p_payload->>'offer_reference'), '');
  v_external_customer_id text := nullif(btrim(coalesce(v_customer->>'external_customer_id', p_payload->>'external_customer_id')), '');
  v_identity_number text := regexp_replace(coalesce(v_customer->>'identity_number', v_customer->>'soc_id', ''), '[^0-9]', '', 'g');
  v_org_number text := regexp_replace(coalesce(v_customer->>'organization_number', v_customer->>'org_number', ''), '[^0-9]', '', 'g');
  v_email text := lower(nullif(btrim(v_customer->>'email'), ''));
  v_customer_id uuid;
  v_site_id uuid;
  v_contract_id uuid;
  v_poa_id uuid;
  v_customer_reference text;
  v_site_reference text;
  v_contract_reference text;
  v_poa_reference text;
  v_customer_number text;
  v_contract_name text;
  v_contract_type text;
  v_energy_direction text;
  v_publication_version_id uuid;
  v_contract_product_version_id uuid;
  v_contract_product_id uuid;
  v_price_plan_id uuid;
  v_price_plan_version_id uuid;
  v_price_book_id uuid;
  v_legal_bundle_version_id uuid;
  v_agreement_accepted_at timestamptz;
  v_signed boolean := false;
  v_now timestamptz := now();
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;
  if p_company_id is null or p_api_client_id is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode='22023', message='partner_api_contract_payload_invalid';
  end if;
  if not exists (
    select 1
    from public.integration_api_clients c
    where c.id = p_api_client_id
      and c.company_id = p_company_id
      and c.status = 'active'
  ) then
    raise exception using errcode='42501', message='partner_api_client_not_active_for_company';
  end if;

  if v_customer_type = 'company' then
    v_customer_type := 'business';
  end if;
  if v_customer_type not in ('private', 'business', 'association') then
    raise exception using errcode='22023', message='partner_api_customer_type_invalid';
  end if;
  if v_site_type = 'production' then
    v_energy_direction := 'production';
  elsif v_site_type = 'consumption' then
    v_energy_direction := 'consumption';
  else
    raise exception using errcode='22023', message='partner_api_site_electricity_type_invalid';
  end if;
  if v_offer_reference is null then
    raise exception using errcode='22023', message='partner_api_offer_reference_required';
  end if;
  if v_email is null or position('@' in v_email) <= 1 then
    raise exception using errcode='22023', message='partner_api_customer_email_required';
  end if;
  if v_external_customer_id is null then
    raise exception using errcode='22023', message='partner_api_external_customer_id_required';
  end if;
  if v_customer_type = 'private' and length(v_identity_number) < 10 then
    raise exception using errcode='22023', message='partner_api_customer_identity_number_required';
  end if;
  if v_customer_type in ('business','association') and length(v_org_number) < 10 then
    raise exception using errcode='22023', message='partner_api_customer_organization_number_required';
  end if;
  if nullif(btrim(coalesce(v_site->>'street', v_site->>'address', '')), '') is null
     or nullif(btrim(coalesce(v_site->>'postal_code', v_site->>'zip_code', '')), '') is null
     or nullif(btrim(v_site->>'city'), '') is null then
    raise exception using errcode='22023', message='partner_api_site_address_required';
  end if;

  v_offer := public.gridex_resolve_partner_api_offer_v1(
    p_company_id,
    v_offer_reference,
    case when v_customer_type = 'association' then null else v_customer_type end
  );
  v_publication_version_id := (v_offer->>'publication_version_id')::uuid;
  v_contract_product_version_id := (v_offer->>'contract_product_version_id')::uuid;
  v_contract_product_id := (v_offer->>'contract_product_id')::uuid;
  v_price_plan_id := nullif(v_offer->>'price_plan_id','')::uuid;
  v_price_plan_version_id := nullif(v_offer->>'price_plan_version_id','')::uuid;
  v_price_book_id := nullif(v_offer->>'price_book_id','')::uuid;
  v_legal_bundle_version_id := nullif(v_offer->>'legal_bundle_version_id','')::uuid;
  v_contract_type := coalesce(nullif(v_offer->>'contract_type',''), 'variable');
  v_energy_direction := coalesce(nullif(v_offer->>'energy_direction',''), v_energy_direction);

  select coalesce(nullif(btrim(cp.name), ''), 'API contract')
  into v_contract_name
  from public.contract_product_versions cpv
  join public.contract_products cp on cp.id = cpv.contract_product_id
  where cpv.id = v_contract_product_version_id
    and (cp.company_id = p_company_id or cp.company_id is null)
  limit 1;
  v_contract_name := coalesce(v_contract_name, 'API contract');

  if nullif(btrim(v_agreement->>'accepted_at'),'') is not null then
    begin
      v_agreement_accepted_at := (v_agreement->>'accepted_at')::timestamptz;
    exception when others then
      raise exception using errcode='22023', message='partner_api_agreement_accepted_at_invalid';
    end;
    v_signed :=
      nullif(btrim(v_agreement->>'signer_name'),'') is not null
      and nullif(btrim(v_agreement->>'evidence_reference'),'') is not null;
    if not v_signed then
      raise exception using errcode='22023', message='partner_api_agreement_evidence_required';
    end if;
  end if;

  insert into public.customers(
    company_id,
    customer_type,
    status,
    first_name,
    last_name,
    full_name,
    company_name,
    personal_number,
    identity_number,
    org_number,
    organization_number,
    email,
    phone,
    source,
    acquisition_channel,
    external_customer_id,
    billing_street,
    billing_postal_code,
    billing_city,
    billing_country,
    metadata
  ) values (
    p_company_id,
    v_customer_type,
    'active',
    nullif(btrim(v_customer->>'first_name'),''),
    nullif(btrim(v_customer->>'last_name'),''),
    nullif(btrim(concat_ws(' ', v_customer->>'first_name', v_customer->>'last_name')),''),
    nullif(btrim(v_customer->>'company_name'),''),
    case when v_customer_type = 'private' then v_identity_number else null end,
    case when v_customer_type = 'private' then v_identity_number else null end,
    case when v_customer_type <> 'private' then v_org_number else null end,
    case when v_customer_type <> 'private' then v_org_number else null end,
    v_email,
    nullif(btrim(coalesce(v_customer->>'phone', v_customer->>'cell_phone')),''),
    'api',
    'partner_api',
    v_external_customer_id,
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,street}', v_customer->>'invoice_address')),''),
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,postal_code}', v_customer->>'zip_code')),''),
    nullif(btrim(coalesce(v_customer#>>'{invoice_address,city}', v_customer->>'city')),''),
    upper(coalesce(nullif(btrim(coalesce(v_customer#>>'{invoice_address,country}', v_customer->>'country')),''), 'SE')),
    jsonb_build_object(
      'source_channel','partner_api',
      'api_client_id',p_api_client_id,
      'external_payload_metadata',coalesce(p_payload->'metadata','{}'::jsonb)
    )
  )
  returning id, customer_reference, customer_number
  into v_customer_id, v_customer_reference, v_customer_number;

  insert into public.customer_sites(
    company_id,
    customer_id,
    site_name,
    site_type,
    status,
    facility_id,
    street,
    address,
    postal_code,
    city,
    country,
    move_in_date,
    annual_consumption_kwh,
    metadata
  ) values (
    p_company_id,
    v_customer_id,
    coalesce(nullif(btrim(v_site->>'name'),''), concat_ws(', ', coalesce(v_site->>'street', v_site->>'address'), v_site->>'city')),
    v_site_type,
    'draft',
    nullif(regexp_replace(coalesce(v_site->>'facility_id',''), '[^0-9]', '', 'g'),''),
    nullif(btrim(coalesce(v_site->>'street', v_site->>'address')),''),
    nullif(btrim(coalesce(v_site->>'address', v_site->>'street')),''),
    nullif(btrim(coalesce(v_site->>'postal_code', v_site->>'zip_code')),''),
    nullif(btrim(v_site->>'city'),''),
    upper(coalesce(nullif(btrim(v_site->>'country'),''), 'SE')),
    case when nullif(btrim(v_site->>'move_in_date'),'') is null then null else (v_site->>'move_in_date')::date end,
    case when nullif(btrim(v_site->>'annual_consumption_kwh'),'') is null then null else (v_site->>'annual_consumption_kwh')::numeric end,
    jsonb_build_object('source_channel','partner_api','api_client_id',p_api_client_id)
  )
  returning id, facility_reference
  into v_site_id, v_site_reference;

  insert into public.customer_contracts(
    company_id,
    customer_id,
    site_id,
    customer_site_id,
    source_type,
    status,
    contract_name,
    contract_type,
    signed_at,
    agreement_channel,
    is_distance_agreement,
    requested_start_date,
    requested_start_mode,
    offer_reference,
    contract_product_id,
    contract_product_version_id,
    contract_publication_version_id,
    legal_bundle_version_id,
    price_plan_id,
    price_plan_version_id,
    price_book_id,
    energy_direction,
    customer_number,
    external_customer_id,
    metadata
  ) values (
    p_company_id,
    v_customer_id,
    v_site_id,
    v_site_id,
    'api',
    case when v_signed then 'signed' else 'pending_signature' end,
    v_contract_name,
    v_contract_type,
    case when v_signed then v_agreement_accepted_at else null end,
    'api',
    coalesce((v_agreement->>'distance_agreement')::boolean, true),
    case when nullif(btrim(p_payload->>'requested_start_date'),'') is null then null else (p_payload->>'requested_start_date')::date end,
    coalesce(nullif(btrim(p_payload->>'requested_start_mode'),''), 'earliest_possible'),
    v_offer_reference,
    v_contract_product_id,
    v_contract_product_version_id,
    v_publication_version_id,
    v_legal_bundle_version_id,
    v_price_plan_id,
    v_price_plan_version_id,
    v_price_book_id,
    v_energy_direction,
    v_customer_number,
    v_external_customer_id,
    jsonb_build_object(
      'source_channel','partner_api',
      'api_client_id',p_api_client_id,
      'agreement_evidence_reference',nullif(btrim(v_agreement->>'evidence_reference'),''),
      'agreement_signer_name',nullif(btrim(v_agreement->>'signer_name'),'')
    )
  )
  returning id, customer_contract_reference
  into v_contract_id, v_contract_reference;

  if jsonb_typeof(p_payload->'power_of_attorney') = 'object'
     and coalesce((v_poa->>'accepted')::boolean, false) then
    insert into public.powers_of_attorney(
      company_id,
      customer_id,
      site_id,
      customer_site_id,
      contract_id,
      customer_contract_id,
      scope,
      status,
      signed_at,
      accepted_at,
      signer_name,
      signer_identity_number,
      method,
      accepted_source,
      source,
      document_path,
      document_hash,
      evidence_payload,
      metadata,
      customer_number,
      external_customer_id
    ) values (
      p_company_id,
      v_customer_id,
      v_site_id,
      v_site_id,
      v_contract_id,
      v_contract_id,
      case
        when lower(coalesce(v_poa->>'transaction_type','switch')) = 'switch' then 'supplier_switch'
        else 'supplier_switch'
      end,
      'signed',
      coalesce(nullif(v_poa->>'accepted_at','')::timestamptz, v_now),
      coalesce(nullif(v_poa->>'accepted_at','')::timestamptz, v_now),
      nullif(btrim(v_poa->>'signer_name'),''),
      nullif(regexp_replace(coalesce(v_poa->>'signer_identity_number',''), '[^0-9]', '', 'g'),''),
      lower(coalesce(nullif(btrim(v_poa->>'poa_type'),''), 'web')),
      'partner_api',
      'partner_api',
      nullif(btrim(v_poa->>'document_path'),''),
      nullif(btrim(v_poa->>'document_sha256'),''),
      jsonb_build_object(
        'evidence_reference', nullif(btrim(v_poa->>'evidence_reference'),''),
        'transaction_type', upper(coalesce(nullif(btrim(v_poa->>'transaction_type'),''), 'SWITCH'))
      ),
      jsonb_build_object('source_channel','partner_api','api_client_id',p_api_client_id),
      v_customer_number,
      v_external_customer_id
    )
    returning id, power_of_attorney_reference
    into v_poa_id, v_poa_reference;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'contract_reference', v_contract_reference,
    'status', case when v_signed then 'signed' else 'pending_signature' end,
    'customer', jsonb_build_object(
      'customer_reference', v_customer_reference,
      'customer_number', v_customer_number
    ),
    'site', jsonb_build_object('site_reference', v_site_reference),
    'power_of_attorney',
      case when v_poa_reference is null then null
           else jsonb_build_object('power_of_attorney_reference', v_poa_reference)
      end
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_partner_webhook_subscription_v1(p_company_id uuid, p_api_client_id uuid, p_name text, p_endpoint_url text, p_event_types text[], p_secret text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_secret_id uuid;
  v_row public.webhook_subscriptions%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;
  if p_company_id is null or p_api_client_id is null then
    raise exception using errcode='22023', message='partner_api_webhook_identity_required';
  end if;
  if not exists (
    select 1 from public.integration_api_clients c
    where c.id = p_api_client_id and c.company_id = p_company_id and c.status = 'active'
  ) then
    raise exception using errcode='42501', message='partner_api_client_not_active_for_company';
  end if;
  if nullif(btrim(p_name),'') is null then
    raise exception using errcode='22023', message='partner_api_webhook_name_required';
  end if;
  if p_endpoint_url !~ '^https://[^[:space:]]+$' then
    raise exception using errcode='22023', message='partner_api_webhook_https_required';
  end if;
  if coalesce(cardinality(p_event_types),0) = 0 then
    raise exception using errcode='22023', message='partner_api_webhook_event_types_required';
  end if;
  if exists (
    select 1
    from unnest(p_event_types) event_type
    where event_type not in (
      'customer.created',
      'customer.updated',
      'site.created',
      'site.updated',
      'power_of_attorney.created',
      'contract.created',
      'contract.status_changed',
      'invoice.created',
      'invoice.updated',
      -- retained compatibility event for existing Partner API subscriptions
      'metering_values.updated'
    )
  ) then
    raise exception using errcode='22023', message='partner_api_webhook_event_type_invalid';
  end if;
  if nullif(p_secret,'') is null or char_length(p_secret) < 32 then
    raise exception using errcode='22023', message='partner_api_webhook_secret_too_short';
  end if;

  select vault.create_secret(
    p_secret,
    'gridex_webhook_' || replace(gen_random_uuid()::text,'-',''),
    'Gridex Partner API webhook signing secret'
  ) into v_secret_id;

  insert into public.webhook_subscriptions(
    company_id,
    api_client_id,
    name,
    description,
    endpoint_url,
    event_types,
    status,
    signing_algorithm,
    signing_secret_ref,
    signing_secret_hash,
    custom_headers,
    timeout_ms,
    max_attempts,
    metadata
  ) values (
    p_company_id,
    p_api_client_id,
    btrim(p_name),
    nullif(btrim(coalesce(p_description,'')),''),
    btrim(p_endpoint_url),
    p_event_types,
    'active',
    'HMAC-SHA256',
    v_secret_id::text,
    encode(extensions.digest(convert_to(p_secret,'utf8'),'sha256'),'hex'),
    '{}'::jsonb,
    10000,
    8,
    jsonb_build_object('source','partner_api','secret_store','supabase_vault')
  )
  returning * into v_row;

  return jsonb_build_object(
    'webhook_subscription_reference', v_row.webhook_subscription_reference,
    'name', v_row.name,
    'endpoint_url', v_row.endpoint_url,
    'event_types', to_jsonb(v_row.event_types),
    'status', v_row.status,
    'created_at', v_row.created_at
  );
exception
  when others then
    if v_secret_id is not null and not exists (
      select 1 from public.webhook_subscriptions
      where signing_secret_ref = v_secret_id::text
    ) then
      delete from vault.secrets where id = v_secret_id;
    end if;
    raise;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_customer_contact_change_v1(p_company_id uuid, p_customer_id uuid, p_actor_kind text, p_actor_user_id uuid, p_api_client_id uuid, p_portal_identity_id text, p_channel text, p_expected_updated_at timestamp with time zone, p_customer_patch jsonb, p_contact_patch jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_allowed_customer constant text[] := ARRAY[
    'customer_type','status','first_name','last_name','full_name','company_name','personal_number','org_number',
    'email','phone','invoice_email','preferred_language','apartment_number','metadata'
  ];
  v_allowed_contact constant text[] := ARRAY['name','email','phone'];
  v_customer public.customers%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_contact public.customer_contacts%ROWTYPE;
  v_contact_before jsonb := NULL;
  v_contact_after jsonb := NULL;
  v_changes jsonb := '{}'::jsonb;
  v_contact_changes jsonb := '{}'::jsonb;
  v_key text;
  v_event_id uuid;
  v_now timestamptz := clock_timestamp();
  v_idempotency_key text;
BEGIN
  IF p_actor_kind NOT IN ('staff','customer_portal') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_actor_kind_invalid';
  END IF;
  IF p_actor_kind='staff' AND p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_staff_actor_required';
  END IF;
  IF p_actor_kind='customer_portal' AND p_api_client_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_api_client_required';
  END IF;
  IF p_channel NOT IN ('ops','customer_api','phone','staff_api') OR p_channel IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='contact_change_channel_invalid';
  END IF;
  IF p_channel='staff_api' THEN
    IF p_actor_kind IS DISTINCT FROM 'staff' THEN
      RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='contact_change_staff_api_actor_invalid';
    END IF;
    PERFORM public.gridex_staff_assert_write_actor_v1(p_company_id,p_actor_user_id,p_api_client_id,'masterdata.write');
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(coalesce(p_customer_patch,'{}'::jsonb)) LOOP
    IF NOT v_key = ANY(v_allowed_customer) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_field_not_allowed:'||v_key;
    END IF;
  END LOOP;
  FOR v_key IN SELECT jsonb_object_keys(coalesce(p_contact_patch,'{}'::jsonb)) LOOP
    IF NOT v_key = ANY(v_allowed_contact) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='contact_change_contact_field_not_allowed:'||v_key;
    END IF;
  END LOOP;

  v_idempotency_key := CASE WHEN p_idempotency_key IS NULL THEN NULL
    WHEN p_channel='staff_api' THEN 'customer.contact_changed:'||p_company_id||':staff_api:'||p_api_client_id||':'||p_customer_id||':'||p_idempotency_key
    ELSE 'customer.contact_changed:'||p_company_id||':'||p_idempotency_key END;

  -- Idempotent replay: the same key returns the recorded result without writing again.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_event_id FROM public.domain_events
      WHERE company_id=p_company_id AND idempotency_key=v_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object('replayed',true,'domain_event_id',v_event_id);
    END IF;
  END IF;

  SELECT * INTO v_customer FROM public.customers
    WHERE id=p_customer_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='customer_not_found_in_scope';
  END IF;

  -- Staff: the canonical resolver grants masterdata.write in exactly this company (active member
  -- with the permission) or to an active platform superadmin; disabled/banned users never pass.
  IF p_actor_kind='staff'
     AND p_channel <> 'staff_api'
     AND NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'masterdata.write'),false) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='contact_change_actor_not_authorized';
  END IF;

  IF v_customer.merged_into_customer_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_merged_write_conflict';
  END IF;

  IF p_expected_updated_at IS NOT NULL AND v_customer.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='contact_change_version_conflict';
  END IF;
  IF v_customer.status='archived' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='contact_change_customer_archived';
  END IF;

  v_before := to_jsonb(v_customer);
  SELECT jsonb_object_agg(e.key, jsonb_build_object('from', v_before->e.key, 'to', e.value))
    INTO v_changes
    FROM jsonb_each(coalesce(p_customer_patch,'{}'::jsonb)) e
    WHERE (v_before->e.key) IS DISTINCT FROM e.value;
  v_changes := coalesce(v_changes,'{}'::jsonb);

  IF v_changes <> '{}'::jsonb THEN
    UPDATE public.customers c SET
      customer_type = CASE WHEN p_customer_patch ? 'customer_type' THEN p_customer_patch->>'customer_type' ELSE c.customer_type END,
      status = CASE WHEN p_customer_patch ? 'status' THEN p_customer_patch->>'status' ELSE c.status END,
      first_name = CASE WHEN p_customer_patch ? 'first_name' THEN p_customer_patch->>'first_name' ELSE c.first_name END,
      last_name = CASE WHEN p_customer_patch ? 'last_name' THEN p_customer_patch->>'last_name' ELSE c.last_name END,
      full_name = CASE WHEN p_customer_patch ? 'full_name' THEN p_customer_patch->>'full_name' ELSE c.full_name END,
      company_name = CASE WHEN p_customer_patch ? 'company_name' THEN p_customer_patch->>'company_name' ELSE c.company_name END,
      personal_number = CASE WHEN p_customer_patch ? 'personal_number' THEN p_customer_patch->>'personal_number' ELSE c.personal_number END,
      org_number = CASE WHEN p_customer_patch ? 'org_number' THEN p_customer_patch->>'org_number' ELSE c.org_number END,
      email = CASE WHEN p_customer_patch ? 'email' THEN p_customer_patch->>'email' ELSE c.email END,
      phone = CASE WHEN p_customer_patch ? 'phone' THEN p_customer_patch->>'phone' ELSE c.phone END,
      invoice_email = CASE WHEN p_customer_patch ? 'invoice_email' THEN p_customer_patch->>'invoice_email' ELSE c.invoice_email END,
      preferred_language = CASE WHEN p_customer_patch ? 'preferred_language' THEN p_customer_patch->>'preferred_language' ELSE c.preferred_language END,
      apartment_number = CASE WHEN p_customer_patch ? 'apartment_number' THEN p_customer_patch->>'apartment_number' ELSE c.apartment_number END,
      metadata = CASE WHEN p_customer_patch ? 'metadata' THEN p_customer_patch->'metadata' ELSE c.metadata END,
      updated_at = v_now
    WHERE c.id=v_customer.id AND c.company_id=p_company_id
    RETURNING * INTO v_customer;
  END IF;
  v_after := to_jsonb(v_customer);

  IF coalesce(p_contact_patch,'{}'::jsonb) <> '{}'::jsonb THEN
    SELECT * INTO v_contact FROM public.customer_contacts
      WHERE company_id=p_company_id AND customer_id=p_customer_id AND is_primary
      ORDER BY created_at ASC LIMIT 1 FOR UPDATE;
    IF FOUND THEN
      v_contact_before := to_jsonb(v_contact);
      SELECT jsonb_object_agg(e.key, jsonb_build_object('from', v_contact_before->e.key, 'to', e.value))
        INTO v_contact_changes
        FROM jsonb_each(p_contact_patch) e
        WHERE (v_contact_before->e.key) IS DISTINCT FROM e.value;
      v_contact_changes := coalesce(v_contact_changes,'{}'::jsonb);
      IF v_contact_changes <> '{}'::jsonb THEN
        UPDATE public.customer_contacts cc SET
          name = CASE WHEN p_contact_patch ? 'name' THEN p_contact_patch->>'name' ELSE cc.name END,
          email = CASE WHEN p_contact_patch ? 'email' THEN p_contact_patch->>'email' ELSE cc.email END,
          phone = CASE WHEN p_contact_patch ? 'phone' THEN p_contact_patch->>'phone' ELSE cc.phone END
        WHERE cc.id=v_contact.id AND cc.company_id=p_company_id AND cc.customer_id=p_customer_id
        RETURNING to_jsonb(cc.*) INTO v_contact_after;
      END IF;
    ELSIF p_contact_patch ? 'name' OR p_contact_patch ? 'email' OR p_contact_patch ? 'phone' THEN
      INSERT INTO public.customer_contacts(company_id,customer_id,type,name,email,phone,title,is_primary)
      VALUES (p_company_id,p_customer_id,'primary',p_contact_patch->>'name',p_contact_patch->>'email',p_contact_patch->>'phone',NULL,true)
      RETURNING to_jsonb(customer_contacts.*) INTO v_contact_after;
      v_contact_changes := jsonb_build_object('created', true);
    END IF;
  END IF;

  IF v_changes = '{}'::jsonb AND v_contact_changes = '{}'::jsonb THEN
    RETURN jsonb_build_object('replayed',false,'changed',false,'customer_updated_at',v_customer.updated_at);
  END IF;

  INSERT INTO public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  VALUES (
    p_company_id, p_actor_user_id, 'customer', p_customer_id::text, 'customer_profile_updated',
    (SELECT coalesce(jsonb_object_agg(k, v->'from'),'{}'::jsonb) FROM jsonb_each(v_changes) x(k,v)),
    (SELECT coalesce(jsonb_object_agg(k, v->'to'),'{}'::jsonb) FROM jsonb_each(v_changes) x(k,v)),
    jsonb_build_object(
      'channel', p_channel,
      'actor_type', CASE WHEN p_actor_kind='staff' THEN 'staff' ELSE 'customer_portal_account' END,
      'api_client_id', p_api_client_id,
      'portal_identity_id', p_portal_identity_id,
      'primary_contact_changes', v_contact_changes,
      'transaction', 'gridex_customer_contact_change_v1'
    )
  );

  -- Durable integration intent. Only changed field names leave the database; values stay internal.
  INSERT INTO public.domain_events(company_id,event_type,aggregate_type,aggregate_id,subject_customer_id,actor_user_id,source,idempotency_key,payload)
  VALUES (
    p_company_id, 'customer.contact_changed', 'customer', p_customer_id::text, p_customer_id, p_actor_user_id,
    CASE WHEN p_channel='staff_api' THEN 'staff_api' WHEN p_actor_kind='staff' THEN 'ops' ELSE 'customer_api' END,
    v_idempotency_key,
    jsonb_build_object(
      'changed_fields', (SELECT coalesce(jsonb_agg(k ORDER BY k),'[]'::jsonb) FROM jsonb_object_keys(v_changes) k),
      'primary_contact_changed', v_contact_changes <> '{}'::jsonb,
      'channel',p_channel,
      'api_client_id',p_api_client_id,
      'actor_user_id',p_actor_user_id,
      'customer_version', v_customer.updated_at
    )
  ) RETURNING id INTO v_event_id;

  INSERT INTO public.event_outbox(company_id,domain_event_id,destination_type,destination_key,status,attempts,max_attempts,available_at,payload)
  VALUES (p_company_id, v_event_id, 'webhook', 'webhook_fanout_v1', 'queued', 0, 12, v_now,
    jsonb_build_object('event_type','customer.contact_changed','aggregate_type','customer','aggregate_id',p_customer_id::text));

  RETURN jsonb_build_object(
    'replayed', false,
    'changed', true,
    'domain_event_id', v_event_id,
    'customer_updated_at', v_customer.updated_at,
    'changes', v_changes,
    'primary_contact_changes', v_contact_changes
  );
END
$function$

CREATE OR REPLACE FUNCTION public.gridex_finalize_customer_contract_signature_v1(p_token_hash text, p_signed_ip_hash text DEFAULT NULL::text, p_signed_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_request public.customer_contract_signature_requests%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_customer public.customers%rowtype;
  v_company public.companies%rowtype;
  v_price public.contract_price_snapshots%rowtype;
  v_legal_versions jsonb;
  v_signature jsonb;
  v_signature_hash text;
  v_acceptance jsonb;
  v_acceptance_hash text;
  v_customer_type text;
  v_withdrawal_required boolean;
  v_withdrawal_deadline timestamptz;
  v_event jsonb;
begin
  if coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='signature_token_invalid'; end if;
  select * into v_request from public.customer_contract_signature_requests where token_hash=p_token_hash for update;
  if not found then raise exception using errcode='P0002',message='signature_link_not_found'; end if;
  select * into v_contract from public.customer_contracts where id=v_request.customer_contract_id and company_id=v_request.company_id for update;
  if v_request.used_at is not null then
    if v_contract.status in ('signed','active','terminated','cancelled','expired') and v_contract.signed_at is not null then
      return public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash) || jsonb_build_object('already_signed',true);
    end if;
    raise exception using errcode='55000',message='signature_link_already_used';
  end if;
  if v_request.revoked_at is not null then raise exception using errcode='55000',message='signature_link_revoked'; end if;
  if v_request.expires_at<=now() then raise exception using errcode='55000',message='signature_link_expired'; end if;
  select * into v_company from public.companies where id=v_request.company_id for share;
  if not found or not coalesce(v_company.is_active,false) or coalesce(v_company.lifecycle_status,'')<>'active' or v_company.suspended_at is not null then
    raise exception using errcode='55000',message='signature_tenant_not_operational';
  end if;
  if v_contract.status<>'pending_signature' or v_contract.signed_at is not null then
    raise exception using errcode='23514',message='contract_not_pending_signature';
  end if;
  select * into v_customer from public.customers where id=v_contract.customer_id and company_id=v_contract.company_id;
  select * into v_price from public.contract_price_snapshots where id=v_contract.contract_price_snapshot_id and company_id=v_contract.company_id and contract_id=v_contract.id;
  if not found or nullif(v_price.snapshot_hash,'') is null then raise exception using errcode='23514',message='signature_pricing_snapshot_missing'; end if;

  if not exists(
    select 1 from public.contract_publication_versions cpv
    join public.contract_publications cp on cp.id=cpv.contract_publication_id
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id and ta.company_id=v_contract.company_id
    join public.contract_product_versions ctv on ctv.id=cpv.contract_product_version_id
    join public.price_plan_versions ppv on ppv.id=cpv.price_plan_version_id
    join public.legal_bundle_versions lbv on lbv.id=cpv.legal_bundle_version_id
    where cpv.id=v_contract.contract_publication_version_id
      and cpv.contract_product_version_id=v_contract.contract_product_version_id
      and cpv.price_plan_version_id=v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and cpv.status='published' and cpv.locked_at is not null
      and ctv.status='approved' and ctv.locked_at is not null
      and ppv.status in ('published','approved','active') and ppv.locked_at is not null
      and lbv.status='published' and lbv.locked_at is not null and cardinality(lbv.unresolved_variables)=0
  ) then raise exception using errcode='23514',message='signature_exact_locked_chain_invalid'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'legal_bundle_version_document_id',d.id,'module_key',d.module_key,'title',d.title,
    'legal_document_version',coalesce(d.template_version,left(d.content_sha256,12)),
    'document_sha256',d.content_sha256,'body_sha256',d.content_sha256
  ) order by d.sort_order,d.id),'[]'::jsonb)
  into v_legal_versions from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id;
  if jsonb_array_length(v_legal_versions)=0 then raise exception using errcode='23514',message='signature_legal_document_set_missing'; end if;

  v_signature:=jsonb_build_object(
    'schema','gridex_online_contract_signature_v1','company_id',v_contract.company_id,'customer_id',v_contract.customer_id,
    'contract_id',v_contract.id,'signature_request_id',v_request.id,'channel',v_request.channel,'accepted_at',now(),
    'recipient_email',v_request.recipient_email,'contract_number',v_contract.contract_number,'offer_reference',v_contract.offer_reference,
    'contract_publication_version_id',v_contract.contract_publication_version_id,'contract_product_version_id',v_contract.contract_product_version_id,
    'price_plan_version_id',v_contract.price_plan_version_id,'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_price_snapshot_id',v_contract.contract_price_snapshot_id,'pricing_snapshot_sha256',v_price.snapshot_hash,
    'legal_versions',v_legal_versions,'tenant_communication_snapshot_sha256',v_contract.tenant_communication_snapshot_sha256,
    'request_evidence',jsonb_build_object('ip_hash',p_signed_ip_hash,'user_agent',left(p_signed_user_agent,1000))
  );
  v_signature_hash:=encode(extensions.digest(convert_to(v_signature::text,'UTF8'),'sha256'),'hex');
  v_acceptance:=jsonb_build_object(
    'schema','gridex_contract_acceptance_v1','signature_request_id',v_request.id,'contract_id',v_contract.id,
    'accepted_at',v_signature->>'accepted_at','channel',v_request.channel,'signing_method','secure_link_click',
    'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash,'legal_versions',v_legal_versions
  );
  v_acceptance_hash:=encode(extensions.digest(convert_to(v_acceptance::text,'UTF8'),'sha256'),'hex');

  insert into public.customer_legal_acceptances(
    company_id,customer_id,contract_id,acceptance_type,legal_text_version_id,
    legal_bundle_version_document_id,legal_module_key,legal_document_version,legal_document_sha256,
    accepted_at,accepted_ip_hash,accepted_user_agent,source,snapshot,metadata
  )
  select v_contract.company_id,v_contract.customer_id,v_contract.id,
    case public.gridex_legacy_legal_type_for_module(d.module_key)
      when 'privacy_policy' then 'privacy_policy' when 'withdrawal' then 'withdrawal_info'
      when 'power_of_attorney' then 'power_of_attorney' when 'price_terms' then 'price_snapshot' else 'terms' end,
    null,d.id,d.module_key,coalesce(d.template_version,left(d.content_sha256,12)),d.content_sha256,
    (v_signature->>'accepted_at')::timestamptz,p_signed_ip_hash,left(p_signed_user_agent,1000),'customer_portal',
    jsonb_build_object('signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash),
    jsonb_build_object('channel',v_request.channel,'pricing_snapshot_sha256',v_price.snapshot_hash)
  from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
  on conflict do nothing;

  insert into public.customer_contract_acceptances(
    company_id,customer_contract_id,contract_publication_version_id,accepted_at,channel,signing_method,
    ip_hash,user_agent,customer_identity_snapshot,power_of_attorney_snapshot,acceptance_snapshot,acceptance_sha256
  ) values(
    v_contract.company_id,v_contract.id,v_contract.contract_publication_version_id,(v_signature->>'accepted_at')::timestamptz,
    v_request.channel,'secure_link_click',p_signed_ip_hash,left(p_signed_user_agent,1000),
    jsonb_strip_nulls(jsonb_build_object('customer_id',v_customer.id,'customer_number',coalesce(v_contract.customer_number,v_customer.customer_number),'email',v_customer.email,'customer_type',v_customer.customer_type)),
    '{}',v_acceptance,v_acceptance_hash
  ) on conflict (customer_contract_id,acceptance_sha256) do nothing;

  insert into public.customer_contract_evidence(company_id,customer_contract_id,evidence_type,evidence_snapshot,evidence_sha256,captured_at)
  values(v_contract.company_id,v_contract.id,'online_acceptance',v_signature,v_signature_hash,(v_signature->>'accepted_at')::timestamptz)
  on conflict (customer_contract_id,evidence_type,evidence_sha256) do nothing;

  select coalesce(v_customer.customer_type,'private') into v_customer_type;
  select exists(select 1 from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id and d.module_key in ('withdrawal','withdrawal_right','withdrawal_form','distance_contract_information','pre_contract_information')) into v_withdrawal_required;
  v_withdrawal_deadline:=case when v_customer_type='private' and v_withdrawal_required then (v_signature->>'accepted_at')::timestamptz+interval '14 days' else null end;

  update public.customer_contracts set
    status='signed',signed_at=(v_signature->>'accepted_at')::timestamptz,
    is_distance_agreement=true,withdrawal_deadline_at=v_withdrawal_deadline,
    legal_versions_snapshot=v_legal_versions,signature_snapshot=v_signature,signature_snapshot_sha256=v_signature_hash,
    signed_ip_hash=p_signed_ip_hash,signed_user_agent=left(p_signed_user_agent,1000),locked_at=(v_signature->>'accepted_at')::timestamptz,
    lifecycle_stage='agreement_signed',signed_version=coalesce(terms_version,contract_version,'v1'),terms_signed_version=coalesce(terms_version,'v1'),
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('signature_status','signed','signature_method','secure_link_click','signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash),
    updated_at=now()
  where id=v_contract.id and company_id=v_contract.company_id
  returning * into v_contract;

  update public.customer_contract_signature_requests set used_at=(v_signature->>'accepted_at')::timestamptz where id=v_request.id;

  v_event:=public.gridex_record_customer_contract_event_v1(
    v_contract.company_id,v_contract.id,v_contract.customer_id,'signed',(v_signature->>'accepted_at')::timestamptz,
    'Avtal signerat online via säker engångslänk',
    jsonb_build_object('signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash,'channel',v_request.channel),
    null,null,
    encode(extensions.digest(convert_to((v_request.id::text||':signed'),'UTF8'),'sha256'),'hex')
  );

  return public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash) || jsonb_build_object('already_signed',false,'withdrawal_deadline_at',v_withdrawal_deadline);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_finalize_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_public_contract_offer_id uuid, p_offer_reference text, p_accepted_at timestamp with time zone, p_legal_versions jsonb, p_signature_snapshot jsonb, p_signature_snapshot_sha256 text, p_signed_ip_hash text DEFAULT NULL::text, p_signed_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract public.customer_contracts%rowtype;
  v_customer_type text;
  v_expected_count integer;
  v_submitted_count integer;
  v_withdrawal_required boolean;
  v_withdrawal_deadline timestamptz;
begin
  if p_company_id is null or p_contract_id is null or p_application_id is null or p_accepted_at is null then
    raise exception using errcode='22023',message='company_contract_application_and_acceptance_time_required';
  end if;
  if jsonb_typeof(coalesce(p_legal_versions,'null'::jsonb))<>'array' then
    raise exception using errcode='22023',message='legal_versions_must_be_array';
  end if;

  select * into v_contract from public.customer_contracts
  where id=p_contract_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='customer_contract_not_found_for_tenant'; end if;
  if v_contract.public_contract_offer_id<>p_public_contract_offer_id
     or v_contract.offer_reference is distinct from p_offer_reference
     or v_contract.contract_publication_version_id is null then
    raise exception using errcode='23514',message='contract_not_bound_to_exact_publication';
  end if;

  select coalesce(c.customer_type,'private') into v_customer_type
  from public.customers c where c.id=v_contract.customer_id and c.company_id=p_company_id;
  v_customer_type:=coalesce(v_customer_type,'private');

  with expected as (
    select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
           d.legacy_legal_text_version_id legal_id
    from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and d.legacy_legal_text_version_id is not null
  ) select count(*) into v_expected_count from expected;
  if v_expected_count=0 then raise exception using errcode='23514',message='exact_legal_document_set_missing'; end if;

  with submitted as (
    select distinct item->>'type' legal_type,(item->>'id')::uuid legal_id
    from jsonb_array_elements(p_legal_versions) item
    where nullif(item->>'type','') is not null and nullif(item->>'id','') is not null
  ) select count(*) into v_submitted_count from submitted;
  if v_submitted_count<>v_expected_count or exists (
    with expected as (
      select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
             d.legacy_legal_text_version_id legal_id
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
        and d.legacy_legal_text_version_id is not null
    ), submitted as (
      select distinct item->>'type' legal_type,(item->>'id')::uuid legal_id
      from jsonb_array_elements(p_legal_versions) item
      where nullif(item->>'type','') is not null and nullif(item->>'id','') is not null
    )
    select 1 from expected e full join submitted s using(legal_type,legal_id)
    where e.legal_id is null or s.legal_id is null
  ) then
    raise exception using errcode='23514',message='submitted_legal_versions_do_not_match_exact_publication';
  end if;

  if exists (
    with expected as (
      select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
             d.legacy_legal_text_version_id legal_id
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
        and d.legacy_legal_text_version_id is not null
    )
    select 1 from expected e
    where not exists (
      select 1 from public.customer_legal_acceptances a
      where a.company_id=p_company_id and a.contract_id=p_contract_id
        and a.contract_application_id=p_application_id and a.legal_text_version_id=e.legal_id
        and a.accepted_at=p_accepted_at
        and a.acceptance_type=case e.legal_type
          when 'terms' then 'terms' when 'privacy_policy' then 'privacy_policy'
          when 'withdrawal' then 'withdrawal_info' when 'power_of_attorney' then 'power_of_attorney'
          when 'price_terms' then 'price_snapshot' end
    )
  ) then raise exception using errcode='23514',message='exact_legal_acceptance_evidence_incomplete'; end if;

  select exists(
    select 1 from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and public.gridex_legacy_legal_type_for_module(d.module_key)='withdrawal'
  ) into v_withdrawal_required;
  v_withdrawal_deadline:=case when v_customer_type='private' and v_withdrawal_required then p_accepted_at+interval '14 days' else null end;

  update public.customer_contracts set
    status='signed',signed_at=p_accepted_at,is_distance_agreement=true,
    withdrawal_deadline_at=v_withdrawal_deadline,legal_versions_snapshot=p_legal_versions,
    signature_snapshot=coalesce(p_signature_snapshot,'{}'::jsonb),
    signature_snapshot_sha256=p_signature_snapshot_sha256,signed_ip_hash=p_signed_ip_hash,
    signed_user_agent=left(p_signed_user_agent,1000),locked_at=p_accepted_at,
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'signature_status','signed','signature_finalized_at',now(),
      'signature_snapshot_sha256',p_signature_snapshot_sha256,
      'contract_publication_version_id',v_contract.contract_publication_version_id
    ),updated_at=now()
  where id=p_contract_id and company_id=p_company_id;

  return jsonb_build_object('contract_id',p_contract_id,'status','signed','signed_at',p_accepted_at,
    'withdrawal_deadline_at',v_withdrawal_deadline,'public_contract_offer_id',p_public_contract_offer_id,
    'offer_reference',p_offer_reference,'signature_snapshot_sha256',p_signature_snapshot_sha256);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_prepare_staff_identity_delivery_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE registration jsonb; i public.company_invitations%rowtype; d public.tenant_staff_identity_deliveries%rowtype; actor uuid; payload jsonb; delivery_id uuid;
BEGIN
 registration:=public.gridex_staff_identity_registration_v1(p_command,true);
 i:=public.gridex_staff_identity_invitation_v1(p_command,true);
 SELECT * INTO d FROM public.tenant_staff_identity_deliveries WHERE invitation_id=i.id FOR UPDATE;
 IF FOUND THEN
  IF d.company_id<>i.company_id OR d.api_client_id<>(p_command->>'api_client_id')::uuid OR d.provider_id<>(p_command->>'provider_id')::uuid OR d.local_auth_issuer<>registration->>'auth_issuer'
  THEN RAISE EXCEPTION 'staff_identity_delivery_mismatch' USING ERRCODE='42501'; END IF;
  RETURN d.request_payload||jsonb_build_object('request_hash',d.request_hash);
 END IF;
 IF i.invited_user_id IS NOT NULL OR i.status<>'pending' OR i.token IS NULL
 THEN RAISE EXCEPTION 'staff_identity_existing_actor_requires_explicit_binding' USING ERRCODE='42501'; END IF;
 actor:=gen_random_uuid(); delivery_id:=gen_random_uuid();
 INSERT INTO auth.users(id,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,is_anonymous)
 VALUES(actor,'{}','{}',now(),now(),false);
 -- Contact/display data is explicit invitation data, never a GoTrue credential.
 INSERT INTO public.user_profiles(id,email,full_name,user_status) VALUES(actor,lower(btrim(i.email)),i.full_name,'active');
 INSERT INTO public.tenant_staff_actor_anchors(actor_user_id,company_id,invitation_id) VALUES(actor,i.company_id,i.id);
 payload:=jsonb_build_object('delivery_id',delivery_id,'actor_user_id',actor,'company_id',i.company_id,'api_client_id',(p_command->>'api_client_id')::uuid,
  'provider_id',(p_command->>'provider_id')::uuid,'invitation_id',i.id,'recipient_email',lower(btrim(i.email)),'full_name',i.full_name,
  'auth_issuer',registration->>'auth_issuer','callback_url',(registration->>'origin')||'/auth/invitation?token='||i.token::text);
 INSERT INTO public.tenant_staff_identity_deliveries(id,company_id,api_client_id,provider_id,invitation_id,actor_user_id,local_auth_issuer,recipient_email,request_payload,request_hash)
 VALUES(delivery_id,i.company_id,(p_command->>'api_client_id')::uuid,(p_command->>'provider_id')::uuid,i.id,actor,registration->>'auth_issuer',lower(btrim(i.email)),payload,public.canonical_json_sha256(payload));
 RETURN payload||jsonb_build_object('request_hash',public.canonical_json_sha256(payload));
END $function$

CREATE OR REPLACE FUNCTION public.gridex_record_staff_identity_delivery_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE registration jsonb; i public.company_invitations%rowtype; d public.tenant_staff_identity_deliveries%rowtype; b public.tenant_staff_identity_bindings%rowtype; r jsonb:=p_command->'verified_receipt'; subject uuid;
BEGIN
 registration:=public.gridex_staff_identity_registration_v1(p_command,true); i:=public.gridex_staff_identity_invitation_v1(p_command,true);
 SELECT * INTO d FROM public.tenant_staff_identity_deliveries WHERE id=(p_command->>'delivery_id')::uuid AND invitation_id=i.id AND company_id=i.company_id FOR UPDATE;
 subject:=nullif(r->>'local_auth_subject','')::uuid;
 IF NOT FOUND OR subject IS NULL OR subject=d.actor_user_id OR d.api_client_id<>(p_command->>'api_client_id')::uuid OR d.provider_id<>(p_command->>'provider_id')::uuid
  OR d.local_auth_issuer<>registration->>'auth_issuer' OR r IS DISTINCT FROM jsonb_build_object('request_hash',d.request_hash,'company_id',d.company_id,'api_client_id',d.api_client_id,
   'provider_id',d.provider_id,'invitation_id',d.invitation_id,'delivery_id',d.id,'local_auth_subject',subject,'auth_issuer',d.local_auth_issuer,'email',d.recipient_email,'status','sent')
 THEN RAISE EXCEPTION 'staff_identity_delivery_receipt_invalid' USING ERRCODE='42501'; END IF;
 IF d.status='sent' AND d.receipt_payload IS DISTINCT FROM r THEN RAISE EXCEPTION 'staff_identity_delivery_receipt_changed' USING ERRCODE='42501'; END IF;
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE invitation_id=i.id FOR UPDATE;
 IF FOUND THEN
  IF b.status='revoked' OR b.api_client_id<>d.api_client_id OR b.provider_id<>d.provider_id OR b.local_auth_issuer<>d.local_auth_issuer OR b.local_user_id<>subject OR b.actor_user_id<>d.actor_user_id
  THEN RAISE EXCEPTION 'staff_identity_binding_mismatch' USING ERRCODE='42501'; END IF;
 ELSE
  INSERT INTO public.tenant_staff_identity_bindings(company_id,api_client_id,provider_id,local_auth_issuer,local_user_id,actor_user_id,provider_configuration,invitation_id,delivery_id)
  VALUES(d.company_id,d.api_client_id,d.provider_id,d.local_auth_issuer,subject,d.actor_user_id,p_command->'verified_provider',d.invitation_id,d.id) RETURNING * INTO b;
 END IF;
 IF d.status='prepared' THEN UPDATE public.tenant_staff_identity_deliveries SET status='sent',receipt_payload=r,sent_at=now() WHERE id=d.id; END IF;
 UPDATE public.company_invitations SET invited_user_id=d.actor_user_id,metadata=metadata||jsonb_build_object('provider_delivery_status','sent','tenant_staff_delivery_id',d.id),updated_at=now() WHERE id=i.id;
 RETURN jsonb_build_object('actor_user_id',b.actor_user_id,'binding_id',b.id,'binding_version',b.version);
END $function$

CREATE OR REPLACE FUNCTION public.gridex_assert_staff_command_v1(p_command jsonb, p_replay boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_client_id uuid := nullif(p_command->>'api_client_id','')::uuid;
  v_channel text := p_command->>'channel';
  v_operation text := p_command->>'staff_operation';
  v_role_key text := p_command->>'role_key';
  v_permissions text[];
  v_membership public.company_memberships%rowtype;
  v_company_status text;
  v_company_active boolean;
  v_target_user_id uuid := nullif(p_command->>'user_id','')::uuid;
BEGIN
  IF v_company_id IS NULL OR v_actor_user_id IS NULL OR v_channel IS NULL OR v_channel NOT IN ('ops','staff_api') THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied';
  END IF;
  SELECT status,is_active INTO v_company_status,v_company_active FROM public.companies WHERE id=v_company_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied'; END IF;
  IF v_company_status NOT IN ('active','onboarding') OR v_company_active IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_company_not_operational';
  END IF;
  v_permissions := public.gridex_staff_actor_permissions_v1(v_company_id,v_actor_user_id,v_channel='ops');
  IF NOT ('users.write'=ANY(v_permissions)) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied';
  END IF;
  IF v_channel='staff_api' THEN
    -- Lock the exact actor rows before the client; global OPS administrators
    -- retain their existing separate authority path. No broad Auth grant is used.
    PERFORM 1 FROM public.company_memberships cm
      JOIN public.user_profiles profile ON profile.id=cm.user_id
      JOIN auth.users account ON account.id=cm.user_id
      WHERE cm.company_id=v_company_id AND cm.user_id=v_actor_user_id
      FOR SHARE OF cm,profile,account;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied'; END IF;
    PERFORM 1 FROM public.integration_api_clients client
      WHERE client.id=v_client_id AND client.company_id=v_company_id FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
      SELECT FROM public.integration_api_clients client
      WHERE client.id=v_client_id AND client.company_id=v_company_id AND client.status='active'
        AND client.deleted_at IS NULL AND client.revoked_at IS NULL
        AND (client.expires_at IS NULL OR client.expires_at>clock_timestamp())
        AND 'staff_users.write'=ANY(client.scopes)
    ) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied'; END IF;
    PERFORM public.gridex_staff_assert_external_actor_v1(v_company_id,v_actor_user_id,v_client_id);
    -- Check eligibility after all potentially blocking row locks, before any
    -- replay return or target mutation. Use wall-clock time for current bans.
    IF NOT EXISTS (
      SELECT FROM public.company_memberships cm
        JOIN public.user_profiles profile ON profile.id=cm.user_id
        JOIN auth.users account ON account.id=cm.user_id
        JOIN public.companies company ON company.id=cm.company_id
      WHERE cm.company_id=v_company_id AND cm.user_id=v_actor_user_id
        AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL
        AND profile.user_status='active' AND account.deleted_at IS NULL
        AND (account.banned_until IS NULL OR account.banned_until<=clock_timestamp())
        AND company.status IN ('active','onboarding') AND company.is_active
    ) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied'; END IF;
    v_permissions := public.gridex_staff_actor_permissions_v1(v_company_id,v_actor_user_id,false);
    IF NOT ('users.write'=ANY(v_permissions)) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_permission_denied';
    END IF;
  END IF;
  IF p_replay THEN RETURN; END IF;
  IF v_operation='invite' THEN
    NULL;
  ELSIF v_operation IN ('change_role','disable','enable') THEN
    SELECT * INTO v_membership FROM public.company_memberships
    WHERE company_id=v_company_id AND user_id=v_target_user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='staff_user_not_found'; END IF;
    IF v_operation='enable' THEN
      IF v_membership.status<>'disabled' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_invalid_user_state'; END IF;
      v_role_key := v_membership.role_key;
    ELSIF v_membership.status<>'active' OR NOT v_membership.is_active THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_invalid_user_state';
    END IF;
    IF v_operation='disable' AND v_target_user_id=v_actor_user_id THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_self_disable_forbidden';
    END IF;
    IF v_operation='change_role' AND v_target_user_id=v_actor_user_id
       AND NOT (v_channel='ops' AND public.canonical_actor_is_platform_admin(v_actor_user_id)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_self_role_change_forbidden';
    END IF;
    IF v_membership.status='active' AND v_membership.is_active
       AND v_membership.membership_role IN ('owner','admin','company_admin')
       AND (v_operation='disable' OR (v_operation='change_role' AND v_role_key NOT IN ('company_admin','admin')))
       AND NOT EXISTS (SELECT FROM public.company_memberships other
         WHERE other.company_id=v_company_id AND other.user_id<>v_target_user_id
           AND other.status='active' AND other.is_active
           AND other.membership_role IN ('owner','admin','company_admin')) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='staff_last_admin_required';
    END IF;
  ELSE
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='staff_invalid_operation';
  END IF;
  IF v_operation<>'disable' THEN
    IF v_role_key IS NULL OR NOT EXISTS (
      SELECT FROM public.canonical_tenant_access_role_mapping mapping
      WHERE mapping.role_key=v_role_key AND mapping.is_assignable AND mapping.role_key<>'owner'
    ) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='staff_role_not_assignable'; END IF;
    IF NOT (public.gridex_staff_role_profile_v1(v_role_key)<@v_permissions) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='staff_role_ceiling_exceeded';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_request public.customer_contract_signature_requests%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_customer public.customers%rowtype;
  v_company public.companies%rowtype;
  v_price public.contract_price_snapshots%rowtype;
  v_legal_versions jsonb;
begin
  select * into v_request from public.customer_contract_signature_requests where token_hash=p_token_hash;
  if not found then raise exception using errcode='P0002',message='signature_link_not_found'; end if;
  if v_request.revoked_at is not null then raise exception using errcode='55000',message='signature_link_revoked'; end if;
  if v_request.used_at is null and v_request.expires_at<=now() then raise exception using errcode='55000',message='signature_link_expired'; end if;
  select * into v_contract from public.customer_contracts where id=v_request.customer_contract_id and company_id=v_request.company_id;
  select * into v_customer from public.customers where id=v_request.customer_id and company_id=v_request.company_id;
  select * into v_company from public.companies where id=v_request.company_id;
  select * into v_price from public.contract_price_snapshots where id=v_contract.contract_price_snapshot_id and company_id=v_request.company_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',d.id,'module_key',d.module_key,'title',d.title,
    'version',coalesce(d.template_version,left(d.content_sha256,12)),
    'document_sha256',d.content_sha256,'body',d.rendered_body
  ) order by d.sort_order,d.id),'[]'::jsonb)
  into v_legal_versions
  from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id;
  return jsonb_build_object(
    'request_id',v_request.id,'company_id',v_request.company_id,'customer_id',v_request.customer_id,
    'contract_id',v_contract.id,'contract_number',v_contract.contract_number,'contract_name',v_contract.contract_name,
    'contract_type',v_contract.contract_type,'status',v_contract.status,'signed_at',v_contract.signed_at,
    'used_at',v_request.used_at,'expires_at',v_request.expires_at,'channel',v_request.channel,
    'customer_name',coalesce(v_customer.full_name,v_customer.company_name,concat_ws(' ',v_customer.first_name,v_customer.last_name),v_customer.email),
    'customer_email',v_customer.email,'customer_number',coalesce(v_contract.customer_number,v_customer.customer_number),
    'company_name',v_company.name,'offer_reference',v_contract.offer_reference,
    'starts_at',v_contract.starts_at,'ends_at',v_contract.ends_at,'price_area',coalesce(v_contract.price_area_used,v_price.snapshot_json->>'price_area'),
    'pricing_snapshot',v_price.snapshot_json,'pricing_snapshot_sha256',v_price.snapshot_hash,
    'legal_versions',v_legal_versions,'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_publication_version_id',v_contract.contract_publication_version_id,'price_plan_version_id',v_contract.price_plan_version_id,
    'signature_snapshot_sha256',v_contract.signature_snapshot_sha256
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_is_current_session_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_disabled_at timestamptz;
begin
  if v_user_id is null then
    return false;
  end if;
  if not exists (
    select 1
      from auth.users u
     where u.id = v_user_id
       and u.deleted_at is null
       and (u.banned_until is null or u.banned_until <= now())
  ) then
    return false;
  end if;
  if to_regclass('public.user_profiles') is null then
    return true;
  end if;
  if exists(
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'user_profiles'
      and column_name = 'disabled_at'
  ) then
    execute
      'select profile.user_status,profile.disabled_at
       from public.user_profiles profile where profile.id=$1'
    into v_status, v_disabled_at
    using v_user_id;
  else
    select profile.user_status
    into v_status
    from public.user_profiles profile
    where profile.id = v_user_id;
  end if;
  if coalesce(v_status, 'active') in (
    'disabled',
    'locked_security',
    'removed_from_company',
    'invitation_revoked'
  ) then
    return false;
  end if;
  return v_disabled_at is null;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_resolve_staff_identity_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE registration jsonb; b public.tenant_staff_identity_bindings%rowtype;
BEGIN
 registration:=public.gridex_staff_identity_registration_v1(p_command,false);
 IF p_command->>'local_auth_issuer' IS DISTINCT FROM registration->>'auth_issuer'
  OR (p_command ? 'local_auth_url' AND p_command->>'local_auth_url' IS DISTINCT FROM p_command->'verified_client'->'staff_tenant_auth'->>'url')
 THEN RAISE EXCEPTION 'staff_identity_issuer_mismatch' USING ERRCODE='42501'; END IF;
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE company_id=(p_command->>'company_id')::uuid AND api_client_id=(p_command->>'api_client_id')::uuid
  AND provider_id=(p_command->>'provider_id')::uuid AND local_auth_issuer=p_command->>'local_auth_issuer' AND local_user_id=(p_command->>'local_user_id')::uuid AND status='active' FOR SHARE;
 IF NOT FOUND OR b.provider_configuration IS DISTINCT FROM p_command->'verified_provider' THEN RAISE EXCEPTION 'staff_identity_binding_missing' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.company_memberships cm JOIN public.user_profiles profile ON profile.id=cm.user_id JOIN auth.users u ON u.id=cm.user_id
 WHERE cm.company_id=b.company_id AND cm.user_id=b.actor_user_id FOR SHARE OF cm,profile,u;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM public.gridex_staff_active_membership_v1(b.company_id,b.actor_user_id))
 THEN RAISE EXCEPTION 'staff_identity_actor_inactive' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('actor_user_id',b.actor_user_id,'binding_id',b.id,'binding_version',b.version);
END $function$

CREATE OR REPLACE FUNCTION public.gridex_staff_assert_external_actor_v1(p_company uuid, p_actor uuid, p_client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c public.integration_api_clients%rowtype; b public.tenant_staff_identity_bindings%rowtype; p public.tenant_customer_identity_providers%rowtype;
BEGIN
 SELECT * INTO c FROM public.integration_api_clients WHERE id=p_client AND company_id=p_company FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'staff_identity_client_inactive' USING ERRCODE='42501'; END IF;
 IF NOT c.metadata ? 'staff_tenant_auth' THEN
  IF EXISTS(SELECT FROM public.tenant_staff_actor_anchors WHERE actor_user_id=p_actor)
   OR EXISTS(SELECT FROM public.tenant_staff_identity_bindings WHERE company_id=p_company AND api_client_id=p_client AND actor_user_id=p_actor)
  THEN RAISE EXCEPTION 'staff_identity_registration_removed' USING ERRCODE='42501'; END IF;
  RETURN;
 END IF;
 SELECT * INTO b FROM public.tenant_staff_identity_bindings WHERE company_id=p_company AND api_client_id=p_client AND actor_user_id=p_actor FOR SHARE;
 IF NOT FOUND OR b.status<>'active' OR b.local_auth_issuer IS DISTINCT FROM (c.metadata->'staff_tenant_auth'->>'url')||'/auth/v1'
 THEN RAISE EXCEPTION 'staff_identity_binding_missing' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.tenant_customer_identity_providers WHERE id=b.provider_id AND company_id=p_company FOR SHARE;
 IF NOT FOUND OR NOT p.is_active OR p.purpose<>'staff' OR p.enforcement<>'enforce' OR p.subject_claim<>'sub'
  OR b.provider_configuration IS DISTINCT FROM jsonb_build_object('kind',p.kind,'issuer',p.issuer,'audience',p.audience,'jwks_uri',p.jwks_uri,'public_jwk',p.public_jwk,'subject_claim',p.subject_claim,'enforcement',p.enforcement)
 THEN RAISE EXCEPTION 'staff_identity_provider_changed' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.gridex_staff_assert_write_actor_v1(p_company_id uuid, p_actor_user_id uuid, p_api_client_id uuid, p_permission text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_required_scope text;
  v_permissions text[];
BEGIN
  v_required_scope := CASE p_permission
    WHEN 'masterdata.write' THEN 'staff_customers.write'
    WHEN 'customers.write' THEN 'staff_customers.write'
    WHEN 'cases.write' THEN 'staff_cases.write'
    ELSE NULL
  END;
  IF v_required_scope IS NULL THEN
    RAISE EXCEPTION 'staff_api_actor_not_authorized' USING ERRCODE='42501';
  END IF;

  -- Match S2's company -> membership order. All locks are held until the
  -- enclosing business mutation commits; Auth row locks need this narrow
  -- service-only definer instead of granting access to the whole Auth table.
  PERFORM 1 FROM public.companies c WHERE c.id=p_company_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_api_actor_inactive' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.company_memberships cm
    JOIN public.user_profiles profile ON profile.id=cm.user_id
    JOIN auth.users account ON account.id=cm.user_id
    WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id
    FOR SHARE OF cm,profile,account;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_api_actor_inactive' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.integration_api_clients client
    WHERE client.id=p_api_client_id AND client.company_id=p_company_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_api_client_not_in_scope' USING ERRCODE='42501'; END IF;

  PERFORM public.gridex_staff_assert_external_actor_v1(p_company_id,p_actor_user_id,p_api_client_id);
  -- Read eligibility again only after every potentially blocking lock. In
  -- particular, scope removal/revocation while the client lock is pending must
  -- fail before the caller performs a write.
  IF NOT EXISTS (
    SELECT FROM public.company_memberships cm
      JOIN public.user_profiles profile ON profile.id=cm.user_id
      JOIN auth.users account ON account.id=cm.user_id
      JOIN public.companies c ON c.id=cm.company_id
    WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id
      AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL
      AND profile.user_status='active'
      AND account.deleted_at IS NULL
      AND (account.banned_until IS NULL OR account.banned_until<=clock_timestamp())
      AND c.status IN ('active','onboarding') AND c.is_active
  ) THEN RAISE EXCEPTION 'staff_api_actor_inactive' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS (
    SELECT FROM public.integration_api_clients client
    WHERE client.id=p_api_client_id AND client.company_id=p_company_id
      AND client.status='active' AND client.deleted_at IS NULL AND client.revoked_at IS NULL
      AND (client.expires_at IS NULL OR client.expires_at>clock_timestamp())
      AND v_required_scope=ANY(client.scopes)
  ) THEN RAISE EXCEPTION 'staff_api_client_not_in_scope' USING ERRCODE='42501'; END IF;
  v_permissions := public.gridex_staff_actor_permissions_v1(p_company_id,p_actor_user_id,false);
  IF NOT coalesce(p_permission=ANY(v_permissions),false) THEN
    RAISE EXCEPTION 'staff_api_actor_not_authorized' USING ERRCODE='42501';
  END IF;
END$function$

CREATE OR REPLACE FUNCTION public.gridex_customer_contracts_auto_renew_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_binding_months integer;
  v_notice_months integer;
  v_auto_renew_months integer;
  v_bound_until timestamptz;
  v_notice_until timestamptz;
begin
  v_binding_months := coalesce(new.binding_months, 0);
  v_notice_months := coalesce(new.notice_months, 0);
  v_auto_renew_months := coalesce(new.auto_renew_term_months, new.binding_months);

  if new.auto_renew_enabled and (v_auto_renew_months is null or v_auto_renew_months <= 0) then
    raise exception 'auto_renew_term_months or binding_months must be set when auto_renew_enabled=true';
  end if;

  if new.termination_reason is not null and new.termination_notice_date is null then
    raise exception 'termination_notice_date is required when termination_reason is set';
  end if;

  -- Signing and withdrawal/termination notice legitimately happen before the
  -- future supply start date. Do not compare these evidence timestamps to
  -- starts_at; starts_at is a delivery/lifecycle date, not an agreement date.

  if new.status in ('signed', 'active', 'terminated') and new.starts_at is null then
    raise exception 'starts_at is required when status is signed, active, or terminated';
  end if;

  if new.green_fee_mode = 'none' and coalesce(new.green_fee_value, 0) <> 0 then
    raise exception 'green_fee_value must be null or 0 when green_fee_mode = none';
  end if;

  v_bound_until := public.gridex_add_months_timestamptz(new.starts_at, nullif(v_binding_months, 0));
  v_notice_until := public.gridex_add_months_timestamptz(new.termination_notice_date, nullif(v_notice_months, 0));

  if new.ends_at is null then
    new.ends_at := greatest(v_bound_until, v_notice_until);
  elsif new.termination_notice_date is not null then
    new.ends_at := greatest(new.ends_at, v_bound_until, v_notice_until);
  end if;

  if new.status in ('terminated', 'expired') and new.ends_at is null then
    new.ends_at := greatest(v_bound_until, v_notice_until, new.starts_at);
  end if;

  if new.starts_at is not null and new.ends_at is not null and new.ends_at < new.starts_at then
    raise exception 'ends_at cannot be earlier than starts_at';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assign_customer_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.customer_number is null or btrim(new.customer_number) = '' then
    new.customer_number := public.gridex_next_customer_number(new.company_id);
  end if;
  return new;
end;
