CREATE OR REPLACE FUNCTION public.gridex_partner_contract_event_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_event_type text;
  v_data jsonb;
begin
  if coalesce(new.metadata->>'source_channel','') <> 'partner_api' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_event_type := 'contract.created';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'offer_reference',new.offer_reference
    );
  elsif new.status is distinct from old.status then
    v_event_type := 'contract.status_changed';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'previous_status',old.status,
      'offer_reference',new.offer_reference
    );
  else
    return new;
  end if;

  perform private.gridex_emit_partner_resource_event_v2(
    new.company_id,
    new.customer_id,
    v_event_type,
    'contract',
    new.customer_contract_reference,
    v_data,
    'partner:' || v_event_type || ':' || new.id::text || ':' || coalesce(new.updated_at::text,new.created_at::text,now()::text)
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.gridex_learn_verified_postal_mapping_from_site_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_postal_code text;
  v_city text;
  v_grid_area_code text;
  v_price_area text;
  v_now timestamptz := now();
begin
  if lower(coalesce(new.resolution_status, '')) not in ('facility_verified', 'manual_verified') then
    return new;
  end if;

  v_postal_code := regexp_replace(coalesce(new.postal_code, ''), '[^0-9]', '', 'g');
  v_city := nullif(btrim(new.city), '');
  v_grid_area_code := nullif(upper(regexp_replace(coalesce(new.grid_area_code, ''), '\s+', '', 'g')), '');
  v_price_area := nullif(upper(btrim(new.price_area_code)), '');

  if v_postal_code !~ '^[0-9]{5}$'
     or v_grid_area_code is null
     or v_price_area not in ('SE1', 'SE2', 'SE3', 'SE4') then
    return new;
  end if;

  update public.platform_postal_code_grid_mappings
     set price_area = v_price_area,
         confidence = 1.0,
         is_active = true,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'learned_from', 'verified_customer_site',
           'verification_count', coalesce(nullif(metadata->>'verification_count', '')::integer, 0) + 1,
           'last_verified_at', v_now
         ),
         updated_at = v_now
   where postal_code = v_postal_code
     and coalesce(lower(city), '') = coalesce(lower(v_city), '')
     and coalesce(upper(grid_area_code), '') = v_grid_area_code
     and source = 'verified_customer_site';

  if not found then
    insert into public.platform_postal_code_grid_mappings (
      postal_code,
      city,
      grid_area_code,
      price_area,
      confidence,
      source,
      is_active,
      metadata,
      created_at,
      updated_at
    ) values (
      v_postal_code,
      v_city,
      v_grid_area_code,
      v_price_area,
      1.0,
      'verified_customer_site',
      true,
      jsonb_build_object(
        'learned_from', 'verified_customer_site',
        'verification_count', 1,
        'first_verified_at', v_now,
        'last_verified_at', v_now
      ),
      v_now,
      v_now
    )
    on conflict do nothing;
  end if;

  return new;
end;
$function$

